function [names, values, centroidal] = nominal_parameters_Panda()
%NOMINAL_PARAMETERS_PANDA Nominal parameters of the Panda Simscape model.
%
%   [names, values] = nominal_parameters_Panda() returns symbol names and
%   numerical values for every symbol that can appear in theta_base of the
%   ORIGIN-REFERENCED (parallel-axis) model: m_i, Lc_ix/y/z (centre of mass
%   in MDH frame {i}), link dimensions, and Ixx_i..Iyz_i = inertia about the
%   ORIGIN of MDH frame {i}.
%
%   GENERATED by simulink/generate_identification_data.m from
%   panda_robot.m (loadrobot('frankaEmikaPanda') with the inertial parameters of
%   Gaz et al., IEEE RA-L 2019); do not edit by hand.
%   The centroidal values are expressed in the MDH link frames; the
%   origin-referenced tensor follows from I_o = I_c + m (c'c E3 - c c').

    c.m  = [4.970684 0.646926 3.228604 3.587895 1.225946 1.666555 0.735522];
    c.L1 = 0.333;
    c.L2 = 0.316;
    c.L3 = 0.0825;
    c.L4 = 0.0825;
    c.L5 = 0.384;
    c.L6 = 0.088;
    % centre of mass [x y z] of link i in MDH frame {i} (m)
    c.Lc = [0.003875 0.002081 -0.175;-0.003141 -0.02872 0.003495;0.027518 0.039252 -0.066502;-0.05317 0.104419 0.027454;-0.011953 0.041065 -0.038437;0.060149 -0.014117 -0.010517;0.010517 -0.004251999999 0.061597];
    % centroidal inertia [Ixx Iyy Izz Ixy Ixz Iyz] (kg m^2), MDH frame {i} axes
    c.Ic = [0.70337 0.70661 0.009117 -0.000139 0.006772 0.019169;0.007962 0.02811 0.025995 -0.003925 0.010254 0.000704;0.037242 0.036155 0.01083 -0.004761 -0.011396 -0.012805;0.025853 0.019552 0.028323 0.007796 -0.001332 0.008641;0.035549 0.029474 0.008627 -0.002117 -0.004037 0.000229;0.001964 0.004354 0.005433 0.000109 -0.001158 0.000341;0.012516 0.010027 0.004815 -0.000428 -0.001196 -0.000741];
    centroidal = c;

    names = {};  values = [];
    for i = 1:7
        Ic = [c.Ic(i,1) c.Ic(i,4) c.Ic(i,5); c.Ic(i,4) c.Ic(i,2) c.Ic(i,6); c.Ic(i,5) c.Ic(i,6) c.Ic(i,3)];
        p  = c.Lc(i,:).';
        Io = Ic + c.m(i)*((p.'*p)*eye(3) - p*p.');      % parallel-axis theorem
        names  = [names, {sprintf('m%d',i), sprintf('Lc%dx',i), sprintf('Lc%dy',i), sprintf('Lc%dz',i), ...
                  sprintf('Ixx%d',i), sprintf('Iyy%d',i), sprintf('Izz%d',i), ...
                  sprintf('Ixy%d',i), sprintf('Ixz%d',i), sprintf('Iyz%d',i)}]; %#ok<AGROW>
        values = [values, c.m(i), c.Lc(i,:), Io(1,1), Io(2,2), Io(3,3), Io(1,2), Io(1,3), Io(2,3)]; %#ok<AGROW>
    end
    names  = [names, {'L1', 'L2', 'L3', 'L4', 'L5', 'L6', 'g'}];
    values = [values, c.L1, c.L2, c.L3, c.L4, c.L5, c.L6, 9.81];
end
